@SneakyThrows
@Test
void using_background_service() {
    final AtomicReference<AsyncProxy<Counter>> asyncProxyUnderTest = new AtomicReference<>();
    // given
    removeAllCommandLogEntriesAndCounters();
    // when
    transactionService.runTransactional(Propagation.REQUIRES_NEW, () -> {
        var counter = bookmarkService.lookup(bookmark, Counter.class).orElseThrow();
        assertThat(counter.getNum()).isNull();
        // when
        asyncProxyUnderTest.set(backgroundService.execute(counter));
    }).ifFailureFail();
    // execute async and wait till done
    {
        asyncProxyUnderTest.get().acceptAsync(Counter::bumpUsingDeclaredAction).// let's wait max 5 sec to allow executor to complete before continuing
        tryGet(5, // wait till done
        TimeUnit.SECONDS);
    }
    // then no change to the counter
    transactionService.runTransactional(Propagation.REQUIRES_NEW, () -> {
        var counter = bookmarkService.lookup(bookmark, Counter.class).orElseThrow();
        // still null
        assertThat(counter.getNum()).isNull();
    }).ifFailureFail();
    // but then instead a background command is persisted
    transactionService.runTransactional(Propagation.REQUIRES_NEW, () -> {
        var all = commandLogEntryRepository.findAll();
        assertThat(all).hasSize(1);
        CommandLogEntry commandLogEntry = all.get(0);
        assertThat(commandLogEntry).satisfies(x -> assertThat(x.getTarget()).isEqualTo(bookmark)).satisfies(x -> assertThat(x.getLogicalMemberIdentifier()).isEqualTo("commandlog.test.Counter#bumpUsingDeclaredAction")).satisfies(x -> assertThat(x.getTimestamp()).isNotNull()).satisfies(x -> assertThat(x.getExecuteIn()).isEqualTo(ExecuteIn.BACKGROUND)).satisfies(x -> assertThat(x.getParentInteractionId()).isNotNull()).satisfies(x -> assertThat(x.getCommandDto()).isNotNull()).satisfies(x -> assertThat(x.getStartedAt()).isNull()).satisfies(x -> assertThat(x.getCompletedAt()).isNull()).satisfies(x -> assertThat(x.getResult()).isNull()).satisfies(x -> assertThat(x.getException()).isNullOrEmpty()).satisfies(x -> assertThat(x.getResultSummary()).isNullOrEmpty()).satisfies(x -> assertThat(x.getReplayState()).isEqualTo(ReplayState.UNDEFINED)).satisfies(x -> assertThat(x.getReplayStateFailureReason()).isNull());
    }).ifFailureFail();
    // when (simulate quartz running in the background)
    runBackgroundCommandsJob.execute(mockQuartzJobExecutionContext);
    interactionService.nextInteraction();
    // then bumped
    transactionService.runTransactional(Propagation.REQUIRES_NEW, () -> {
        var counter = bookmarkService.lookup(bookmark, Counter.class).orElseThrow();
        assertThat(counter.getNum()).isEqualTo(1L);
    }).ifFailureFail();
    // and marked as started and completed
    transactionService.runTransactional(Propagation.REQUIRES_NEW, () -> {
        var after = commandLogEntryRepository.findAll();
        assertThat(after).hasSize(1);
        CommandLogEntry commandLogEntryAfter = after.get(0);
        assertThat(commandLogEntryAfter).satisfies(// changed
        x -> assertThat(x.getStartedAt()).isNotNull()).satisfies(// changed
        x -> assertThat(x.getCompletedAt()).isNotNull()).satisfies(// changed
        x -> assertThat(x.getResult()).isNotNull()).satisfies(// changed
        x -> assertThat(x.getResultSummary()).isNotNull());
    }).ifFailureFail();
}

