void setUp() throws Exception {
    causewayInteractionFilter = new CausewayRestfulObjectsInteractionFilter();
    mockFilterConfig = Mockito.mock(FilterConfig.class);
}

@Test
void when_null() throws Exception {
    Mockito.when(mockFilterConfig.getInitParameter(CausewayRestfulObjectsInteractionFilter.PASS_THRU_KEY)).thenReturn(null);
    final List<String> x = causewayInteractionFilter.lookupAndParsePassThru(mockFilterConfig);
    assertEquals(0, x.size());
}

@Test
void when_none() throws Exception {
    Mockito.when(mockFilterConfig.getInitParameter(CausewayRestfulObjectsInteractionFilter.PASS_THRU_KEY)).thenReturn("");
    final List<String> x = causewayInteractionFilter.lookupAndParsePassThru(mockFilterConfig);
    assertEquals(0, x.size());
}

@Test
void when_one() throws Exception {
    Mockito.when(mockFilterConfig.getInitParameter(CausewayRestfulObjectsInteractionFilter.PASS_THRU_KEY)).thenReturn("/abc");
    final List<String> x = causewayInteractionFilter.lookupAndParsePassThru(mockFilterConfig);
    assertEquals(1, x.size());
    assertEquals("/abc", x.get(0));
}

@Test
void when_several() throws Exception {
    Mockito.when(mockFilterConfig.getInitParameter(CausewayRestfulObjectsInteractionFilter.PASS_THRU_KEY)).thenReturn("/abc,/def");
    final List<String> x = causewayInteractionFilter.lookupAndParsePassThru(mockFilterConfig);
    assertEquals(2, x.size());
    assertEquals("/abc", x.get(0));
    assertEquals("/def", x.get(1));
}

